  if (suits.size === 0) items.push({ name:'All Honors', fan:10 });
  else if (suits.size === 1 && !honors) items.push({ name:'Full Flush', fan:6 });
  else if (suits.size === 1) items.push({ name:'Half Flush', fan:3 });
  if (ctx.lastTile) items.push({ name:'Last tile of the wall', fan:1 });
  if (ctx.kongDraw) items.push({ name:'Win on a Kong replacement', fan:1 });
